using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API at the given path.")]
    public static async Task<string> FetchApiData(
        IHttpClientFactory httpClientFactory,
        [Description("The API endpoint path, e.g. /users/1")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum sentence count for the summary")] int? maxSentences = null)
    {
        var instruction = maxSentences.HasValue
            ? $"Summarize the following text in at most {maxSentences} sentences."
            : "Summarize the following text concisely.";

        return
        [
            new(Role.User, $"{instruction}\n\n{text}")
        ];
    }
}

